<style>
:root{--red:#922D20;--paper:#f7f6fb;--ink:#292633;--muted:#898596;--line:#e9e6ef;--lav:#f2edff;--purple:#7061d3}
*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:14px/1.55 Inter,system-ui,-apple-system,"Segoe UI",sans-serif}button,input,select,textarea{font:inherit}button{cursor:pointer}.top{height:70px;background:#fff;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;padding:0 28px;position:sticky;top:0;z-index:2}.brand{display:flex;align-items:center;gap:12px;font-weight:850;letter-spacing:.06em}.brand img{width:42px;height:42px;object-fit:contain;background:#fbf4f0;border-radius:12px;padding:4px}.brand small{display:block;font-size:9px;color:#9993a4;letter-spacing:.16em}.top a{color:var(--red);text-decoration:none;font-weight:700}.wrap{max-width:1450px;margin:auto;padding:30px 26px 70px}.heading{display:flex;justify-content:space-between;align-items:flex-start;gap:20px;margin-bottom:24px}.eyebrow{font-size:10px;letter-spacing:.17em;text-transform:uppercase;color:var(--red);font-weight:800}.heading h1{font-size:30px;letter-spacing:-.04em;margin:5px 0}.heading p{margin:0;color:var(--muted)}.layout{display:grid;grid-template-columns:310px minmax(0,1fr);gap:20px;align-items:start}.panel{background:#fff;border:1px solid var(--line);border-radius:16px;padding:22px;box-shadow:0 5px 22px #30205a05}.panel h2{font-size:19px;margin:0 0 15px}.list{display:grid;gap:8px}.page-item{display:block;width:100%;text-align:left;background:#fff;border:1px solid var(--line);border-radius:11px;padding:13px;color:var(--ink)}.page-item.active,.page-item:hover{border-color:#cfc6fa;background:#f7f4ff}.page-item strong{display:block;font-size:13px}.page-item small{color:var(--muted);display:block;margin-top:3px}.empty{color:var(--muted);font-size:12px;padding:15px 0}.btn{border:1px solid var(--red);background:var(--red);color:#fff;border-radius:10px;padding:10px 14px;font-weight:750;font-size:12px}.btn:hover{filter:brightness(.94)}.btn.secondary{background:#fff;border-color:var(--line);color:#5e596b}.btn.soft{background:var(--lav);border-color:var(--lav);color:var(--purple)}.toolbar{display:flex;gap:8px;flex-wrap:wrap}.field{display:grid;gap:6px;margin:13px 0;font-weight:700;font-size:12px}.field input,.field select,.field textarea{width:100%;border:1px solid #e4e0ea;background:#fdfcff;border-radius:9px;padding:11px 12px;color:var(--ink);font-weight:400;min-width:0}.field textarea{min-height:90px;resize:vertical}.grid2{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.separator{height:1px;background:var(--line);margin:22px 0}.day{border:1px solid var(--line);border-radius:13px;padding:16px;margin:13px 0;background:#fff}.day-content[hidden]{display:none}.day-toggle{display:flex;align-items:center;gap:8px;border:0;background:transparent;color:var(--ink);font-weight:800;padding:8px 0;text-align:left}.day-toggle .chevron{display:inline-block;transition:transform .18s}.day.is-collapsed .day-toggle .chevron{transform:rotate(-90deg)}#add-day{position:fixed;right:22px;bottom:92px;z-index:25;box-shadow:0 6px 20px #30205a25}.images>.day-head{position:sticky;top:76px;z-index:4;background:rgba(255,255,255,.97);backdrop-filter:blur(8px);padding:8px 0;border-bottom:1px solid var(--line)}.images>.day-head .add-image{box-shadow:0 4px 14px #30205a12}.day-head{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:5px}.day-head strong{font-size:14px}.image-row{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr) auto auto;gap:8px;align-items:end}.image-file{display:none}.image-preview{display:block;max-width:190px;max-height:110px;object-fit:cover;border-radius:8px;margin-top:6px}.hero-tools{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.hero-preview{display:block;max-width:220px;max-height:130px;object-fit:cover;border-radius:8px;margin-top:8px}.notice{min-height:22px;margin:10px 0;color:var(--red);font-weight:700;font-size:12px}.help{font-size:11px;color:var(--muted);font-weight:400}.toggle{display:flex;align-items:center;gap:9px;font-weight:700;font-size:12px}.toggle input{width:17px;height:17px;accent-color:var(--red)}.tag{display:inline-flex;padding:4px 8px;background:#eaf7ef;color:#23824b;border-radius:7px;font-size:10px;font-weight:800}.preview-link{display:inline-block;margin-top:10px;color:var(--red);font-weight:750;text-decoration:none}.hidden{display:none!important}.form-actions{position:sticky;bottom:10px;z-index:20;background:rgba(255,255,255,.97);backdrop-filter:blur(10px);padding:12px;border:1px solid var(--line);border-radius:12px;box-shadow:0 8px 24px #30205a18;margin:18px -4px 12px}.form-actions .btn{min-height:42px}@media(max-width:600px){.form-actions{bottom:6px;padding:9px;gap:6px}.form-actions .btn{flex:1}}
@media(max-width:900px){.layout{grid-template-columns:1fr}.list{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:600px){.top{padding:0 13px}.wrap{padding:20px 12px 115px}.panel{padding:16px}.heading{display:block}.heading h1{font-size:25px}.grid2,.image-row{grid-template-columns:1fr}.list{grid-template-columns:1fr}#add-day{right:12px;bottom:104px;max-width:calc(100vw - 24px)}}
</style></head><body>
