<p class="help">La publication rend la page accessible via le lien de prévisualisation public. Vérifiez les textes et les images avant de publier.</p>
<div class="toolbar form-actions"><button class="btn" type="submit" id="save">Enregistrer la page</button><button class="btn secondary" type="button" id="reset">Annuler</button><button class="btn secondary hidden" type="button" id="delete">Supprimer</button></div><div class="notice" id="notice" role="status" aria-live="polite"></div><a id="preview" class="preview-link hidden" target="_blank" rel="noopener">↗ Ouvrir la page publique</a>
</form></section></div></main>
<script>
(() => {
'use strict';
const $=s=>document.querySelector(s); const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let csrf='', pages=[], circuits=[], selected=null, catalogueOptions=[];
async function request(path,options={}){const headers={'Accept':'application/json',...(options.body?{'Content-Type':'application/json'}:{}),...(options.mutate?{'X-CSRF-Token':csrf}:{})};const res=await fetch('../api/'+path,{credentials:'same-origin',...options,headers});const data=await res.json().catch(()=>({}));if(!res.ok)throw new Error(data.error?.message||'Une erreur est survenue.');return data;}
function note(s){$('#notice').textContent=s||''}
function showEditor(){ $('#editor-panel').classList.remove('hidden'); $('#global-notice').classList.add('hidden'); $('#global-notice').textContent=''; }
function hideEditor(message=''){ $('#editor-panel').classList.add('hidden'); $('#global-notice').textContent=message; $('#global-notice').classList.toggle('hidden',!message); }
function resetForm(hide=true){selected=null;$('#page-id').value='';$('#circuit-id').value='';$('#hero-image').value='';$('#hero-file').value='';$('#hero-preview').removeAttribute('src');$('#hero-preview').classList.add('hidden');$('#hero-fr').value='';$('#hero-en').value='';$('#intro-fr').value='';$('#intro-en').value='';$('#published').checked=false;$('#days').innerHTML='';$('#delete').classList.add('hidden');$('#preview').classList.add('hidden');$('#save').textContent='Enregistrer la page';note('');if(hide)hideEditor();else showEditor();renderList();}
function addDay(day={}){const n=$('#days').children.length+1;const section=document.createElement('section');section.className='day';section.innerHTML='<div class="day-head"><button class="day-toggle" type="button" aria-expanded="true"><span class="chevron">▾</span><strong>Journée <span class="day-number">'+n+'</span></strong></button><button class="btn secondary remove-day" type="button">Retirer</button></div><div class="day-content"><div class="grid2"><label class="field">Titre de l’étape *<input class="day-title" required maxlength="220" placeholder="Antananarivo – Antsirabe" value="'+esc(day.title||'')+'"></label><label class="field">Sous-titre<input class="day-subtitle" maxlength="220" placeholder="Route vers les Hautes Terres" value="'+esc(day.subtitle||'')+'"></label></div><label class="field">Description<textarea class="day-description" placeholder="Décrivez les visites, paysages et rencontres…">'+esc(day.description||'')+'</textarea></label><label class="field">Nuitée<input class="day-overnight" maxlength="500" placeholder="Nuitée : hôtel à…" value="'+esc(day.overnight||'')+'"></label><div class="images"><div class="day-head"><strong>Images de l’étape</strong><button class="btn soft add-image" type="button">＋ Image</button></div></div></div>';
 const imgs=section.querySelector('.images');(Array.isArray(day.images)?day.images:[]).forEach(img=>addImage(imgs,img));if(!day.images||!day.images.length)addImage(imgs);section.querySelector('.remove-day').addEventListener('click',()=>{section.remove();renumberDays()});section.querySelector('.day-toggle').addEventListener('click',()=>{const content=section.querySelector('.day-content'),collapsed=!content.hidden;content.hidden=collapsed;section.classList.toggle('is-collapsed',collapsed);section.querySelector('.day-toggle').setAttribute('aria-expanded',String(!collapsed));});section.querySelector('.add-image').addEventListener('click',()=>{if(imgs.querySelectorAll('.image-row').length>=5){note('Maximum 5 images par journée.');return;}addImage(imgs);});$('#days').appendChild(section);renumberDays();}
const imgs=section.querySelector('.images');(Array.isArray(day.images)?day.images:[]).forEach(img=>addImage(imgs,img));if(!day.images||!day.images.length)addImage(imgs);section.querySelector('.remove-day').addEventListener('click',()=>{section.remove();renumberDays()});section.querySelector('.add-image').addEventListener('click',()=>{if(imgs.querySelectorAll('.image-row').length>=5){note('Maximum 5 images par journée.');return;}addImage(imgs);});$('#days').appendChild(section);renumberDays();}
async function uploadImage(file,button,onSuccess){if(!file)return;const old=button.textContent;button.disabled=true;button.textContent='Import…';note('');try{const form=new FormData();form.append('image',file);const response=await fetch('../api/admin/circuit-page-image.php',{method:'POST',credentials:'same-origin',headers:{'X-CSRF-Token':csrf,'Accept':'application/json'},body:form});const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error?.message||'Impossible d’importer cette image.');onSuccess(data.data.path);note('Image importée avec succès.');}catch(error){note(error.message)}finally{button.disabled=false;button.textContent=old;}}
function addImage(container,img={}){const row=document.createElement('div');row.className='image-row';row.innerHTML='<label class="field">URL / chemin image<input class="image-url" placeholder="https://… ou assets/…" value="'+esc(img.url||'')+'"></label><label class="field">Texte alternatif<input class="image-alt" placeholder="Description de la photo" value="'+esc(img.alt||'')+'"></label><button class="btn soft import-image" type="button">Importer</button><button class="btn secondary remove-image" type="button">×</button>';const picker=document.createElement('input');picker.type='file';picker.accept='image/jpeg,image/png,image/webp';picker.className='image-file';row.appendChild(picker);const url=row.querySelector('.image-url');const preview=document.createElement('img');preview.className='image-preview'+(img.url?'':' hidden');preview.alt=img.alt||'Aperçu de l’image';if(img.url)preview.src=img.url;row.querySelector('.field').appendChild(preview);const importButton=row.querySelector('.import-image');importButton.addEventListener('click',()=>picker.click());picker.addEventListener('change',()=>{const file=picker.files?.[0];uploadImage(file,importButton,path=>{url.value=path;preview.src='../'+path;preview.classList.remove('hidden');});});url.addEventListener('change',()=>{if(url.value.trim()){preview.src=url.value.trim().startsWith('uploads/')?'../'+url.value.trim():url.value.trim();preview.classList.remove('hidden')}else preview.classList.add('hidden')});row.querySelector('.remove-image').addEventListener('click',()=>row.remove());container.appendChild(row);}
function renumberDays(){[...$('#days').children].forEach((el,i)=>el.querySelector('.day-number').textContent=i+1)}
function collectDays(){return [...$('#days').children].map(el=>({title:el.querySelector('.day-title').value.trim(),subtitle:el.querySelector('.day-subtitle').value.trim(),description:el.querySelector('.day-description').value.trim(),overnight:el.querySelector('.day-overnight').value.trim(),images:[...el.querySelectorAll('.image-row')].map(row=>({url:row.querySelector('.image-url').value.trim(),alt:row.querySelector('.image-alt').value.trim()})).filter(x=>x.url)}))}
function renderList(){const el=$('#pages-list');if(!pages.length){el.innerHTML='<div class="empty">Aucune page détaillée créée pour le moment.</div>';return;}el.innerHTML=pages.map(p=>'<button type="button" class="page-item '+(selected&&Number(selected.id)===Number(p.id)?'active':'')+'" data-id="'+Number(p.id)+'"><strong>'+esc(p.hero_title_fr||p.title_fr)+'</strong><small>'+esc(p.title_fr)+' · '+(p.is_published?'<span class="tag">Publiée</span>':'Brouillon')+'</small><small>'+((p.days||[]).length)+' journée(s)</small></button>').join('');el.querySelectorAll('[data-id]').forEach(b=>b.addEventListener('click',()=>openPage(pages.find(p=>Number(p.id)===Number(b.dataset.id)))));}
function fillCircuitSelect(selectedId){$('#circuit-id').innerHTML='<option value="">Choisir un circuit…</option>'+circuits.map(c=>'<option value="'+Number(c.id)+'">'+esc(c.title_fr)+' ('+esc(c.slug)+')</option>').join('');if(selectedId)$('#circuit-id').value=String(selectedId);}
function slugify(value){return value.toLocaleLowerCase('fr').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'').slice(0,180);}
function fillNewCircuitOptions(selected={}){
 const fill=(id,type)=>{const el=$(id),items=catalogueOptions.filter(o=>o.option_type===type&&o.is_active);el.innerHTML='<option value="">Non définie</option>'+items.map(o=>'<option value="'+esc(o.option_label)+'">'+esc(o.option_label)+'</option>').join('');if(selected[type])el.value=selected[type];};
 fill('#new-circuit-region','region');fill('#new-circuit-theme','theme');
 const durations=catalogueOptions.filter(o=>o.option_type==='duration'&&o.is_active),durationEl=$('#new-circuit-duration');
 durationEl.innerHTML='<option value="">Choisir une durée…</option>'+durations.map(o=>'<option value="'+esc(o.option_value)+'">'+esc(o.option_label)+'</option>').join('');
 if(selected.duration)durationEl.value=selected.duration;
}
async function refreshNewCircuitOptions(selected={}){
 const result=await request('admin/filter-options.php');catalogueOptions=result.data||[];fillNewCircuitOptions(selected);
}
async function createCatalogueOption(type){
 const notice=$('#create-circuit-notice');
 try{
  let label='',value='';
  if(type==='region'||type==='theme'){
   const promptLabel=type==='region'?'Nom de la région (ex. Boeny, Sofia)':'Nom de la thématique (ex. Nature, Culture)';
   label=(window.prompt(promptLabel)||'').trim();if(!label)return;
   value=slugify(label);if(!value){notice.textContent='Saisissez un nom valide.';return;}
  }else{
   const raw=(window.prompt('Durée en jours (1 à 364), plage (ex. 3-5) ou « sur mesure » :')||'').trim().toLocaleLowerCase('fr');if(!raw)return;
   if(raw==='sur mesure'||raw==='sur-mesure'){value='custom';label='Sur mesure';}
   else if(/^\d{1,3}(?:-\d{1,3})?$/.test(raw)){
    if(raw.includes('-')){const [min,max]=raw.split('-').map(Number);if(min<1||max<min||max>364){notice.textContent='La plage doit être comprise entre 1 et 364 jours.';return;}value=raw;label=min+'–'+max+' jours';}
    else {const days=Number(raw);if(days<1||days>364){notice.textContent='La durée doit être comprise entre 1 et 364 jours.';return;}value=raw;label=days+' jour'+(days>1?'s':'');}
   }else{notice.textContent='Indiquez un nombre de jours (5), une plage (3-5) ou « sur mesure ».';return;}
  }
  const exists=catalogueOptions.some(o=>o.option_type===type&&(o.option_value===value||o.option_label.toLocaleLowerCase('fr')===label.toLocaleLowerCase('fr')));
  if(exists){notice.textContent='Cette option existe déjà. Elle est disponible dans la liste.';await refreshNewCircuitOptions({[type]:type==='duration'?value:label});return;}
  const button=document.querySelector('[data-option-type="'+type+'"]');if(button)button.disabled=true;
  try{
   await request('admin/filter-options.php',{method:'POST',mutate:true,body:JSON.stringify({option_type:type,option_label:label,option_value:value,sort_order:0})});
   await refreshNewCircuitOptions({[type]:type==='duration'?value:label});
   notice.textContent=(type==='region'?'Région':type==='theme'?'Thématique':'Durée')+' créée et sélectionnée.';
  }finally{if(button)button.disabled=false;}
 }catch(error){notice.textContent=error.message||'Impossible de créer cette option.';}
}
function resetCreateCircuit(){['#new-circuit-title','#new-circuit-slug','#new-circuit-summary'].forEach(id=>$(id).value='');$('#create-circuit-notice').textContent='';$('#create-circuit-panel').classList.add('hidden');}
$('#show-create-circuit').addEventListener('click',async()=>{const panel=$('#create-circuit-panel');panel.classList.toggle('hidden');if(!panel.classList.contains('hidden')){try{await refreshNewCircuitOptions();$('#new-circuit-title').focus();}catch(error){$('#create-circuit-notice').textContent='Impossible de charger les paramètres du catalogue : '+error.message;}}});
$('#cancel-create-circuit').addEventListener('click',resetCreateCircuit);
document.querySelectorAll('[data-option-type]').forEach(button=>button.addEventListener('click',()=>createCatalogueOption(button.dataset.optionType)));
$('#new-circuit-title').addEventListener('input',()=>{const slug=$('#new-circuit-slug');if(!slug.dataset.edited)slug.value=slugify($('#new-circuit-title').value);});
$('#new-circuit-slug').addEventListener('input',()=>{$('#new-circuit-slug').dataset.edited='1';});
$('#new-circuit-title').addEventListener('change',()=>{if(!$('#new-circuit-slug').value)$('#new-circuit-slug').value=slugify($('#new-circuit-title').value);});
$('#create-circuit-submit').addEventListener('click',async()=>{
 const title=$('#new-circuit-title').value.trim(),slug=slugify($('#new-circuit-slug').value),summary=$('#new-circuit-summary').value.trim(),duration=$('#new-circuit-duration').value;
 const notice=$('#create-circuit-notice'),button=$('#create-circuit-submit');notice.textContent='';
 if(!title||!slug||!summary){notice.textContent='Renseignez le titre, le slug et le résumé du circuit.';return;}
  if(!/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(slug)){notice.textContent='Le slug doit contenir uniquement des minuscules, chiffres et tirets simples.';return;}
 if(!duration){notice.textContent='Configurez au moins une durée dans les paramètres du catalogue.';return;}
 let durationMin=null,durationMax=null;
 if(duration!=='custom'){const parts=duration.split('-').map(Number);durationMin=parts[0];durationMax=parts[1]||parts[0];}
 button.disabled=true;
 try{
  const payload={slug,title_fr:title,title_en:'',summary_fr:summary,summary_en:'',region:$('#new-circuit-region').value,theme:$('#new-circuit-theme').value,duration_min:durationMin,duration_max:durationMax,image_path:'',is_published:false,sort_order:0};
  const result=await request('admin/circuits.php',{method:'POST',mutate:true,body:JSON.stringify(payload)});
  const list=await request('admin/circuits.php');circuits=list.data||[];fillCircuitSelect(Number(result.data.id));resetCreateCircuit();note('Circuit créé et associé au formulaire. Complétez la page détaillée puis enregistrez-la.'); 
 }catch(error){notice.textContent=error.message;}finally{button.disabled=false;}
});
function openPage(p){if(!p)return;showEditor();selected=p;$('#page-id').value=p.id;fillCircuitSelect(p.circuit_id);$('#hero-image').value=p.hero_image||'';$('#hero-preview').src=p.hero_image?(p.hero_image.startsWith('uploads/')?'../'+p.hero_image:p.hero_image):'';$('#hero-preview').classList.toggle('hidden',!p.hero_image);$('#hero-fr').value=p.hero_title_fr||'';$('#hero-en').value=p.hero_title_en||'';$('#intro-fr').value=p.intro_fr||'';$('#intro-en').value=p.intro_en||'';$('#published').checked=!!p.is_published;$('#days').innerHTML='';(p.days||[]).forEach(addDay);$('#delete').classList.remove('hidden');$('#save').textContent='Enregistrer les modifications';$('#preview').classList.toggle('hidden',!p.is_published);if(p.is_published)$('#preview').href='../circuit-detail.php?slug='+encodeURIComponent(p.slug);note('');renderList();}
async function load(){const list=$('#pages-list');list.innerHTML='<div class="empty">Chargement…</div>';try{const s=await request('admin/session.php');if(!s.data?.authenticated){location.replace('login.php');return;}csrf=s.data.csrfToken||'';const data=await request('admin/circuit-pages.php');pages=data.data||[];circuits=data.circuits||[];fillCircuitSelect();renderList();note('');}catch(e){list.innerHTML='<div class="empty">Impossible de charger les pages : '+esc(e.message)+' <button type="button" class="btn secondary" id="retry-load-pages">Réessayer</button></div>';$('#retry-load-pages')?.addEventListener('click',load);note(e.message);}}
$('#hero-import').addEventListener('click',()=>$('#hero-file').click());
$('#hero-file').addEventListener('change',()=>{const file=$('#hero-file').files?.[0];uploadImage(file,$('#hero-import'),path=>{$('#hero-image').value=path;$('#hero-preview').src='../'+path;$('#hero-preview').classList.remove('hidden');});});
$('#hero-image').addEventListener('change',()=>{const path=$('#hero-image').value.trim();$('#hero-preview').src=path?(path.startsWith('uploads/')?'../'+path:path):'';$('#hero-preview').classList.toggle('hidden',!path);});
$('#new-page').addEventListener('click',()=>{resetForm(false);addDay();$('#circuit-id').focus();});
$('#add-day').addEventListener('click',()=>{if($('#days').children.length>=60){note('Maximum 60 journées par circuit.');return;}addDay();note('')});
$('#reset').addEventListener('click',resetForm);
$('#page-form').addEventListener('submit',async e=>{e.preventDefault();note('');const circuitId=Number($('#circuit-id').value);if(!circuitId){note('Sélectionnez un circuit du catalogue.');return;}const days=collectDays();if(!days.length){note('Ajoutez au moins une journée au programme.');return;}if(days.some(d=>!d.title)){note('Chaque journée doit avoir un titre.');return;}const payload={circuit_id:circuitId,hero_image:$('#hero-image').value.trim(),hero_title_fr:$('#hero-fr').value.trim(),hero_title_en:$('#hero-en').value.trim(),intro_fr:$('#intro-fr').value.trim(),intro_en:$('#intro-en').value.trim(),is_published:$('#published').checked,days};const id=$('#page-id').value;if(id)payload.id=Number(id);$('#save').disabled=true;try{const r=await request('admin/circuit-pages.php',{method:id?'PATCH':'POST',mutate:true,body:JSON.stringify(payload)});await load();if(payload.is_published){selected=null;hideEditor('Page publiée avec succès. Le formulaire est masqué. Cliquez sur « Nouvelle page » pour créer une autre page, ou sélectionnez une page enregistrée pour la modifier.');renderList();}else{const p=pages.find(x=>Number(x.id)===Number(r.data.id));if(p)openPage(p);note('Brouillon enregistré avec succès.');}}catch(err){note(err.message)}finally{$('#save').disabled=false;}});
$('#delete').addEventListener('click',async()=>{if(!selected||!confirm('Supprimer cette page détaillée ? Le circuit du catalogue sera conservé.'))return;try{await request('admin/circuit-pages.php?id='+selected.id,{method:'DELETE',mutate:true});resetForm(true);await load();hideEditor('Page supprimée.');}catch(e){note(e.message)}});
$('#logout').addEventListener('click',async()=>{try{await request('admin/session.php',{method:'POST',mutate:true,body:JSON.stringify({action:'logout'})})}catch(_){}location.replace('login.php')});
load();
})();
</script></body></html>